def flatten_dict(d, sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Args:
        d (dict): The dictionary to flatten.
        sep (str, optional): The separator to use for concatenating keys. Defaults to '.'.

    Returns:
        dict: A new dictionary with all keys flattened and their corresponding values.
    """
    flat_dict = {}

    def _flatten(obj, parent_key=''):
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_key = f"{parent_key}{sep}{key}" if parent_key else key
                _flatten(value, new_key)
        elif isinstance(obj, list):
            # If the value is a list, we iterate through its items and flatten them.
            # The key for each item will be parent_key[index]
            for i, item in enumerate(obj):
                new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
                _flatten(item, new_key)
        else:
            flat_dict[parent_key] = obj

    _flatten(d)
    return flat_dict

