    @wraps(fn)
    def wrapper(*args, **kwargs):
        current_delay = delay
        for attempt in range(attempts):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                if attempt < attempts - 1:
                    print(f"Attempt {attempt + 1}/{attempts} failed: {e}. Retrying in {current_delay:.2f} seconds...")
